import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";
import StaffNavbar from "../components/StaffNavbar";

export default function Products() {

  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);

  const [selectedProduct, setSelectedProduct] = useState(null);
  const [qty, setQty] = useState("");

  /* =========================
     FETCH PRODUCTS
  ========================= */
  const fetchProducts = () => {

    setLoading(true);

    fetch("http://localhost/Capstone--Development/customer/api_products.php?action=list")
      .then(res => res.json())
      .then(data => {

        if (Array.isArray(data)) {
          setProducts(data);
        } else {
          setProducts([]);
        }

      })
      .catch(() => setProducts([]))
      .finally(() => setLoading(false));

  };

  useEffect(() => {
    fetchProducts();
  }, []);

  /* =========================
     UPDATE STOCK
  ========================= */
  const updateStock = (type) => {

    if (!selectedProduct) return;

    fetch("http://localhost/Capstone--Development/staff/api_update_stock.php", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        id: selectedProduct.id,
        qty: Number(qty),
        type
      })
    })
      .then(res => res.json())
      .then(data => {

        if (data.status === "success") {
          fetchProducts();
          setSelectedProduct(null);
          setQty("");
        } else {
          alert(data.message || "Update failed");
        }

      });

  };

  /* =========================
     STOCK STATUS COLOR
  ========================= */
  const getStockColor = (stock) => {

    if (stock <= 0) return "text-red-600";
    if (stock <= 5) return "text-yellow-600";
    return "text-green-600";

  };

  return (

    <div className="bg-[#fafafa] min-h-screen">

      {/* NAVBAR */}
      <StaffNavbar />

      {/* PAGE WRAPPER */}
      <div className="p-8 xl:p-10 pt-24">

        {/* HEADER */}
        <div className="mb-10">

          <p className="text-[10px] uppercase tracking-[0.3em] text-gray-400">
            Inventory Control
          </p>

          <h1 className="text-4xl font-bold">
            Products Management
          </h1>

        </div>

        {/* LOADING */}
        {loading ? (
          <p className="text-gray-400">Loading products...</p>
        ) : (

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">

            {products.map(product => (

              <motion.div
                key={product.id}
                whileHover={{ y: -5 }}
                className="bg-white rounded-2xl shadow-md overflow-hidden border border-gray-100"
              >

                {/* IMAGE */}
                <div className="h-40 overflow-hidden">
                  <img
                    src={`http://localhost/Capstone--Development/uploads/${product.image}`}
                    className="w-full h-full object-cover"
                    alt={product.name}
                  />
                </div>

                {/* CONTENT */}
                <div className="p-5">

                  <h2 className="font-bold text-lg">
                    {product.name}
                  </h2>

                  <p className="text-xs text-gray-400 mb-2">
                    {product.category}
                  </p>

                  {/* STOCK */}
                  <p className="text-sm mb-3">
                    Stock:
                    <span className={`font-bold ml-2 ${getStockColor(product.stock)}`}>
                      {product.stock ?? 0}
                    </span>
                  </p>

                  {/* BUTTON */}
                  <button
                    onClick={() => setSelectedProduct(product)}
                    className="w-full bg-black text-white text-xs py-2 rounded-lg hover:bg-gray-800"
                  >
                    Manage Stock
                  </button>

                </div>

              </motion.div>

            ))}

          </div>

        )}

        {/* =========================
            STOCK MODAL
        ========================= */}
        {selectedProduct && (

          <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50">

            <div className="bg-white w-[350px] rounded-2xl p-6 shadow-xl">

              <h2 className="text-lg font-bold mb-2">
                {selectedProduct.name}
              </h2>

              <p className="text-sm text-gray-500 mb-4">
                Current Stock: {selectedProduct.stock ?? 0}
              </p>

              {/* INPUT */}
              <input
                type="number"
                value={qty}
                onChange={(e) => setQty(e.target.value)}
                placeholder="Enter quantity"
                className="w-full border p-2 rounded-lg mb-4"
              />

              {/* ACTIONS */}
              <div className="flex gap-2">

                <button
                  onClick={() => updateStock("in")}
                  className="flex-1 bg-green-500 text-white py-2 rounded-lg text-sm"
                >
                  Stock In
                </button>

                <button
                  onClick={() => updateStock("out")}
                  className="flex-1 bg-red-500 text-white py-2 rounded-lg text-sm"
                >
                  Stock Out
                </button>

              </div>

              {/* CLOSE */}
              <button
                onClick={() => setSelectedProduct(null)}
                className="mt-3 w-full text-xs text-gray-500"
              >
                Cancel
              </button>

            </div>

          </div>

        )}

      </div>

    </div>

  );

}
